#!/usr/bin/env node
import { spawnSync } from 'node:child_process';
import { existsSync, readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { AuthoritativeLedger, InvalidTransitionError } from './ledger.mjs';
import { MinimalSpine } from './spine.mjs';
import { invoke } from './runner.mjs';

const optionsByCommand = {
  init: ['plan'], status: [], delegate: ['milestone'],
  'run-milestone': ['milestone', 'zen-cmd', 'timeout', 'cwd'], candidate: ['file'],
  'record-zen': ['file'], blocked: ['milestone', 'status', 'blocker', 'evidence'],
  replan: ['plan'], 'resolve-blocker': ['id', 'evidence'], complete: [],
  'invoke-role': ['role', 'packet'],
};
const readJson = path => JSON.parse(readFileSync(path, 'utf8'));

function parseArgs(argv) {
  const [command, ...args] = argv;
  if (!Object.hasOwn(optionsByCommand, command)) throw new TypeError('Unknown spine command');
  const options = {};
  for (let i = 0; i < args.length; i += 2) {
    const key = args[i].slice(2);
    if (!args[i].startsWith('--') || !['ledger', ...optionsByCommand[command]].includes(key)
        || Object.hasOwn(options, key) || !args[i + 1]?.trim() || args[i + 1].startsWith('--')) {
      throw new TypeError(`Invalid, duplicate, or missing-value option: ${args[i]}`);
    }
    options[key] = args[i + 1];
  }
  const required = key => {
    if (!options[key]) throw new TypeError(`--${key} is required`);
    return options[key];
  };
  required('ledger');
  for (const key of optionsByCommand[command]) {
    if (!['zen-cmd', 'blocker', 'evidence', 'timeout', 'cwd'].includes(key)
        || (command === 'resolve-blocker' && key === 'evidence')) required(key);
  }
  return { command, options };
}

// The public plan spelling is depends_on; the ledger owns dependencies.
function readPlan(path) {
  const plan = readJson(path);
  if (!plan || typeof plan !== 'object' || !Array.isArray(plan.milestones)) {
    throw new TypeError('Plan must contain milestones');
  }
  return { ...plan, milestones: plan.milestones.map(m => {
    if (m.depends_on !== undefined && m.dependencies !== undefined
        && JSON.stringify(m.depends_on) !== JSON.stringify(m.dependencies)) {
      throw new TypeError('Conflicting depends_on and dependencies');
    }
    return { ...m, dependencies: m.depends_on ?? m.dependencies };
  }) };
}

export function invokeExternalZen(command, request) {
  // This is explicitly a supervisor-supplied shell command, not candidate text.
  const output = spawnSync(command, {
    shell: true, input: JSON.stringify(request) + '\n', encoding: 'utf8',
    timeout: 90000, maxBuffer: 20 * 1024 * 1024,
  });
  if (output.error) throw output.error;
  if (output.status !== 0) throw new Error(`Zen command failed (${output.status}): ${output.stderr}`);
  let verdict = JSON.parse(output.stdout);
  // Official AGY JSON output wraps the role's JSON response in SUCCESS.
  if (verdict?.status === 'SUCCESS' && typeof verdict.response === 'string') {
    verdict = JSON.parse(verdict.response);
  }
  return verdict;
}

async function runMilestone(path, milestone, zenCommand, invokeRole, timeoutMs, cwd) {
  // A fresh ledger validates transition errors using its original error types
  // before MinimalSpine's generic busy check. This copy is never saved.
  AuthoritativeLedger.load(path).delegate(milestone);
  let handoff;
  const handedOff = new Promise(resolveHandoff => { handoff = resolveHandoff; });
  // Wrap invokeRole so the spine's JSON.parse sees a bare JSON object even when
  // the model wraps its packet in prose or markdown fences.
  const extractingInvoke = async (role, packet, opts) => {
    const out = await invokeRole(role, packet, opts);
    if (out?.ok && typeof out.response === 'string') {
      const m = out.response.match(/\{[\s\S]*\}/);
      if (m) {
        out.response = m[0];
        // Normalize candidate_artifact_ref to the string the spine requires:
        // an object {path, sha256, ...} becomes "path@sha256:<hash>".
        try {
          const p = JSON.parse(out.response);
          if (p && typeof p === 'object' && p.candidate_artifact_ref && typeof p.candidate_artifact_ref === 'object') {
            const r = p.candidate_artifact_ref;
            p.candidate_artifact_ref = r.path && r.sha256 ? `${r.path}@sha256:${r.sha256}` : JSON.stringify(r);
            out.response = JSON.stringify(p);
          }
        } catch { /* leave response as-is; spine will surface the parse error */ }
      }
    }
    return out;
  };
  const spine = new MinimalSpine({
    ledgerPath: path, invokeRole: extractingInvoke,
    runnerOptions: { ...(timeoutMs ? { timeout: timeoutMs } : {}), ...(cwd ? { cwd } : {}) },
    invokeZen: zenCommand ? request => invokeExternalZen(zenCommand, request) : request => {
      handoff({ status: 'AWAITING_ZEN', verified: false, zen_request: request });
      // Suspend only this in-memory coordinator at the durable review boundary.
      // No timers or process handles remain. record-zen resumes from disk in a
      // fresh invocation; never fake a verdict or throw (which records failure).
      return new Promise(() => {});
    },
  });
  const running = spine.runMilestone(milestone);
  return zenCommand ? running : Promise.race([running, handedOff]);
}

/** Injectable role transport for deterministic tests; ledger and spine stay real. */
export async function execute(argv, { invokeRole = invoke } = {}) {
  const { command, options: o } = parseArgs(argv);
  const path = o.ledger;
  if (command === 'run-milestone') {
    return { ok: true, ...await runMilestone(path, o.milestone, o['zen-cmd'], invokeRole, o.timeout ? Number(o.timeout) : undefined, o.cwd) };
  }
  const ledger = command === 'init' && !existsSync(path)
    ? new AuthoritativeLedger() : AuthoritativeLedger.load(path);
  let result;
  switch (command) {
    case 'init': ledger.init(readPlan(o.plan)); result = { state: ledger.getState() }; break;
    case 'status': result = { state: ledger.getState() }; break;
    case 'delegate': result = { packet: ledger.delegate(o.milestone) }; break;
    case 'candidate': result = ledger.receiveCandidate(readJson(o.file)); break;
    case 'record-zen': {
      const verdict = readJson(o.file);
      if (verdict?.verdict === 'GO') result = { verification: ledger.recordZenGo(verdict) };
      else if (verdict?.verdict === 'NO-GO') result = { verification: ledger.recordZenNoGo(verdict) };
      else throw new InvalidTransitionError('Zen verdict must be GO or NO-GO');
      break;
    }
    case 'blocked':
      if (!['BLOCKED', 'FAILED'].includes(o.status)) throw new InvalidTransitionError('Status must be BLOCKED or FAILED');
      result = ledger.recordBlockedOrFailure({
        milestoneId: o.milestone, status: o.status, blockers: o.blocker,
        evidence: o.evidence ? { classification: 'OBSERVED', result: o.evidence } : undefined,
      });
      break;
    case 'replan': ledger.materialReplan(readPlan(o.plan)); result = { state: ledger.getState() }; break;
    case 'resolve-blocker': result = ledger.resolveBlocker(o.id, { classification: 'OBSERVED', result: o.evidence }); break;
    case 'complete': result = ledger.declareGlobalCompletion(); break;
    case 'invoke-role': {
      result = await invokeRole(o.role, readJson(o.packet));
      if (!result?.ok) {
        return { ...result, ok: false, error: result?.error ?? 'Invocation failed',
          errorType: result?.errorType ?? result?.error ?? 'InvocationError' };
      }
      break;
    }
  }
  ledger.save(path);
  return { ok: true, ...result };
}

export async function main(argv) {
  try {
    return await execute(argv);
  } catch (error) {
    return { ok: false, error: error.message, errorType: error.name };
  }
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const result = await main(process.argv.slice(2));
  console.log(JSON.stringify(result));
  process.exitCode = result.ok ? 0 : 1;
}

import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { test } from 'node:test';
import { execute } from '../scripts/spine-cli.mjs';
import { AuthoritativeLedger } from '../scripts/ledger.mjs';

const cli = fileURLToPath(new URL('../scripts/spine-cli.mjs', import.meta.url));
const observed = [{ classification: 'OBSERVED', result: 'fixture artifact inspected' }];
const plan = () => ({
  goal: 'Deliver two artifacts', constraints: [], decision_invariants: [], plan_version: 'v1',
  milestones: ['one', 'two'].map((id, i) => ({
    id, title: id, objective: `Deliver ${id}`, acceptance_criteria: ['artifact matches'],
    bounded_scope: [`${id}.txt`], depends_on: i ? ['one'] : [],
  })),
});
const candidate = (id = 'one', version = 'v1', revision = '1') => ({
  milestone_id: id, plan_version: version, status: 'DONE', changes_made: [`${id}.txt`],
  verification_evidence: observed, unresolved_unknowns: [], scope_deviations: [],
  candidate_artifact_ref: `sha256:fixture-${revision}`,
});
const verdict = (ref, patch = {}) => ({
  milestone_id: 'one', plan_version: 'v1', result_ref: ref,
  verdict: 'GO', verification_evidence: observed, ...patch,
});

function fixture(t) {
  const dir = mkdtempSync(join(tmpdir(), 'ntg-spcli-'));
  t.after(() => rmSync(dir, { recursive: true, force: true }));
  const ledger = join(dir, 'ledger.json');
  let sequence = 0;
  const json = value => {
    const path = join(dir, `packet-${sequence++}.json`);
    writeFileSync(path, JSON.stringify(value));
    return path;
  };
  const args = (command, ...rest) => [command, '--ledger', ledger, ...rest];
  const call = (command, rest = [], errorType) => {
    const result = spawnSync(process.execPath, [cli, ...args(command, ...rest)], {
      encoding: 'utf8', timeout: 5000,
    });
    assert.ifError(result.error);
    assert.equal(result.stderr, '');
    const output = JSON.parse(result.stdout);
    assert.equal(result.status, errorType ? 1 : 0, JSON.stringify(output));
    assert.equal(output.ok, !errorType);
    if (errorType) assert.equal(output.errorType, errorType);
    return output;
  };
  const initial = call('init', ['--plan', json(plan())]);
  const stage = (id = 'one', version = 'v1', revision = '1') => {
    call('delegate', ['--milestone', id]);
    return call('candidate', ['--file', json(candidate(id, version, revision))]).result_ref;
  };
  return { dir, ledger, json, args, call, initial, stage };
}

test('init and fresh-process status round-trip; cannot reset existing ledger', t => {
  const f = fixture(t);
  assert.deepEqual(f.call('status').state, f.initial.state);
  assert.equal(f.initial.state.goal, plan().goal);
  assert.deepEqual(f.initial.state.milestones[1].dependencies, ['one']);
  f.call('init', ['--plan', f.json(plan())], 'InvalidTransitionError');
  assert.deepEqual(f.call('status').state, f.initial.state);
});

test('delegate returns complete bounded packet and enforces dependency and active state', t => {
  const f = fixture(t);
  f.call('delegate', ['--milestone', 'two'], 'InvalidTransitionError');
  const packet = f.call('delegate', ['--milestone', 'one']).packet;
  assert.equal(packet.milestone_id, 'one');
  assert.equal(packet.plan_version, 'v1');
  assert.deepEqual(packet.bounded_scope, ['one.txt']);
  assert.deepEqual(packet.acceptance_criteria, ['artifact matches']);
  f.call('delegate', ['--milestone', 'one'], 'InvalidTransitionError');
});

test('candidate persistence; wrong reference and stale version cannot mutate authority', t => {
  const f = fixture(t);
  const ref = f.stage();
  const before = readFileSync(f.ledger, 'utf8');
  f.call('record-zen', ['--file', f.json(verdict('wrong'))], 'MismatchedResultRefError');
  f.call('record-zen', ['--file', f.json(verdict(ref, { plan_version: 'v0' }))], 'StaleVerdictError');
  f.call('record-zen', ['--file', f.json(verdict(ref, { verdict: 'READY' }))], 'InvalidTransitionError');
  assert.equal(readFileSync(f.ledger, 'utf8'), before);
  f.call('record-zen', ['--file', f.json(verdict(ref))]);
  assert.deepEqual(f.call('status').state.completed_milestones, ['one']);
});

test('NO-GO permits fresh repair and completion requires every current GO', t => {
  const f = fixture(t);
  f.call('complete', [], 'InvariantViolationError');
  const first = f.stage();
  f.call('complete', [], 'InvariantViolationError');
  f.call('record-zen', ['--file', f.json(verdict(first, { verdict: 'NO-GO' }))]);
  assert.deepEqual(f.call('status').state.completed_milestones, []);
  const repaired = f.stage('one', 'v1', '2');
  assert.notEqual(first, repaired);
  f.call('record-zen', ['--file', f.json(verdict(repaired))]);
  f.call('complete', [], 'InvariantViolationError');
  const second = f.stage('two');
  f.call('record-zen', ['--file', f.json(verdict(second, { milestone_id: 'two' }))]);
  assert.equal(f.call('complete').completed, true);
  assert.equal(AuthoritativeLedger.load(f.ledger).declareGlobalCompletion().completed, true);
});

test('replan increments version, preserves stale history, rejects active replan and old verdicts', { timeout: 5000 }, async t => {
  const f = fixture(t);
  const ref = f.stage();
  const revised = plan();
  delete revised.plan_version;
  f.call('replan', ['--plan', f.json(revised)], 'InvalidTransitionError');
  f.call('record-zen', ['--file', f.json(verdict(ref))]);
  const state = f.call('replan', ['--plan', f.json(revised)]).state;
  assert.equal(state.plan_version, 'v2');
  assert.equal(state.verification.one.is_stale, true);
  assert.deepEqual(state.completed_milestones, []);
  assert.equal(state.current_milestone, null);
  const fresh = await execute(f.args('run-milestone', '--milestone', 'one'), { invokeRole: roleStub });
  assert.equal(fresh.zen_request.plan_version, 'v2');
  f.call('record-zen', ['--file', f.json(verdict(ref))], 'StaleVerdictError');
  f.call('record-zen', ['--file', f.json(verdict(fresh.zen_request.result_ref, { plan_version: 'v2' }))]);
  assert.deepEqual(f.call('status').state.completed_milestones, ['one']);
});

test('blocked and failed end invocation; resolution needs evidence and never promotes', t => {
  const f = fixture(t);
  f.call('delegate', ['--milestone', 'one']);
  const blocked = f.call('blocked', ['--milestone', 'one', '--status', 'BLOCKED',
    '--blocker', 'Authorization missing', '--evidence', 'permission denied']);
  assert.equal(f.call('status').state.current_milestone, null);
  f.call('complete', [], 'InvariantViolationError');
  const id = blocked.blockers[0].id;
  f.call('resolve-blocker', ['--id', id], 'TypeError');
  f.call('resolve-blocker', ['--id', id, '--evidence', 'user supplied authorization']);
  assert.deepEqual(f.call('status').state.completed_milestones, []);
  f.call('delegate', ['--milestone', 'one']);
  f.call('blocked', ['--milestone', 'one', '--status', 'FAILED', '--evidence', 'executor exited']);
  assert.equal(f.call('status').state.current_milestone, null);
});

const roleStub = async (role, packet) => {
  assert.equal(role, 'bulldozer');
  const contract = JSON.parse(packet.task.slice(packet.task.indexOf('\n') + 1));
  return { ok: true, response: JSON.stringify(candidate(contract.milestone_id, contract.plan_version)) };
};

test('run-milestone suspends at durable Zen request; fresh record-zen resumes it', { timeout: 5000 }, async t => {
  const f = fixture(t);
  const result = await execute(f.args('run-milestone', '--milestone', 'one'), { invokeRole: roleStub });
  assert.equal(result.status, 'AWAITING_ZEN');
  assert.equal(result.verified, false);
  const request = result.zen_request;
  const disk = AuthoritativeLedger.load(f.ledger).getState();
  assert.equal(disk.current_milestone, 'one');
  assert.deepEqual(disk.completed_milestones, []);
  assert.equal(disk.evidence[request.result_ref].result_ref, request.result_ref);
  assert.deepEqual(request.contract.bounded_scope, ['one.txt']);
  f.call('record-zen', ['--file', f.json(verdict(request.result_ref))]);
  assert.deepEqual(f.call('status').state.completed_milestones, ['one']);
});

for (const wrapped of [false, true]) {
  test(`run-milestone invokes external Zen over real stdin/stdout; envelope=${wrapped}`, { timeout: 5000 }, async t => {
    const f = fixture(t);
    const script = join(f.dir, 'zen.mjs');
    writeFileSync(script, `import {readFileSync} from 'node:fs';
const request = JSON.parse(readFileSync(0, 'utf8'));
const disk = JSON.parse(readFileSync(${JSON.stringify(f.ledger)}, 'utf8'));
if (disk.evidence[request.result_ref].result_ref !== request.result_ref) process.exit(2);
const verdict = {milestone_id: request.milestone_id, plan_version: request.plan_version,
result_ref: request.result_ref, verdict: 'GO', verification_evidence: ${JSON.stringify(observed)}};
console.log(JSON.stringify(${wrapped ? "{status: 'SUCCESS', response: JSON.stringify(verdict)}" : 'verdict'}));
`);
    const result = await execute(f.args('run-milestone', '--milestone', 'one', '--zen-cmd',
      `${JSON.stringify(process.execPath)} ${JSON.stringify(script)}`), { invokeRole: roleStub });
    assert.equal(result.verified, true);
    assert.deepEqual(f.call('status').state.completed_milestones, ['one']);
  });
}

test('external Zen failure persists invocation failure without promotion', { timeout: 5000 }, async t => {
  const f = fixture(t);
  await assert.rejects(execute(f.args('run-milestone', '--milestone', 'one', '--zen-cmd', 'exit 7'),
    { invokeRole: roleStub }), /Zen command failed/);
  const state = f.call('status').state;
  assert.equal(state.current_milestone, null);
  assert.deepEqual(state.completed_milestones, []);
  assert.equal(state.evidence.one.failure_evidence[0].status, 'INVOCATION_FAILURE');
});

test('invoke-role passthrough and invalid CLI input fail structurally', async t => {
  const f = fixture(t);
  const packet = { task: 'Produce a bounded advisory plan' };
  const result = await execute(f.args('invoke-role', '--role', 'piledriver', '--packet', f.json(packet)), {
    invokeRole: (role, actual) => {
      assert.equal(role, 'piledriver');
      assert.deepEqual(actual, packet);
      return { ok: true, response: '{"advisory":true}' };
    },
  });
  assert.equal(JSON.parse(result.response).advisory, true);
  f.call('status', ['--unknown', 'value'], 'TypeError');
  f.call('blocked', ['--milestone', 'one', '--status', 'GO'], 'InvalidTransitionError');
});

#!/usr/bin/env node
// driver.mjs — G3 live integration driver for 44G.
// Orchestrates spine-cli commands + real agy invocations against the scratch
// project, capturing transcripts + ledger snapshots per scenario.
import { execFileSync, execSync } from "node:child_process";
import { writeFileSync, readFileSync, copyFileSync, mkdirSync, existsSync, rmSync } from "node:fs";
import { join } from "node:path";

const WT = "/home/sleeg/work/native-gravity-44g";
const EV = "/home/sleeg/work/native-gravity-evidence/44g/g3-live";
const SCRATCH = join(EV, "scratch");
const CLI = join(WT, "scripts/spine-cli.mjs");
const LEDGER = join(EV, "ledger.json");
const T = join(EV, "transcripts");
mkdirSync(T, { recursive: true });
mkdirSync(SCRATCH, { recursive: true });

const log = (msg) => { const line = `[${new Date().toISOString()}] ${msg}`; console.log(line); };
const snap = (name) => { if (existsSync(LEDGER)) copyFileSync(LEDGER, join(T, `ledger-${name}.json`)); };

function cli(...args) {
  const cmd = ["node", CLI, ...args].join(" ");
  log(`CLI: ${args.join(" ")}`);
  try {
    const out = execFileSync("node", [CLI, ...args], { encoding: "utf8", timeout: 600000, cwd: SCRATCH });
    writeFileSync(join(T, `cli-${Date.now()}.json`), out);
    return { ok: true, out, json: JSON.parse(out) };
  } catch (e) {
    const out = (e.stdout || "") + (e.stderr || "");
    writeFileSync(join(T, `cli-err-${Date.now()}.json`), out);
    return { ok: false, out, error: String(e).slice(0, 300) };
  }
}

function agy(agent, prompt, model = "gemini-3.1-pro-low") {
  log(`AGY: --agent ${agent} --print <${prompt.length} chars>`);
  try {
    const out = execFileSync("agy", ["--agent", agent, "--model", model, "--output-format", "json", "--print", prompt], { encoding: "utf8", timeout: 600000, cwd: SCRATCH });
    writeFileSync(join(T, `agy-${agent}-${Date.now()}.json`), out);
    return { ok: true, out, json: JSON.parse(out) };
  } catch (e) {
    const out = (e.stdout || "") + (e.stderr || "");
    writeFileSync(join(T, `agy-${agent}-err-${Date.now()}.json`), out);
    return { ok: false, out, error: String(e).slice(0, 300) };
  }
}

function zen(request) {
  // invoke zen via the wrapper (stdin request -> stdout verdict)
  log(`ZEN: invoking with request for ${request.milestone_id}@${request.plan_version}`);
  try {
    const out = execSync(`SCRATCH_DIR=${SCRATCH} ${EV}/zen-invoke.sh`, { input: JSON.stringify(request), encoding: "utf8", timeout: 600000 });
    writeFileSync(join(T, `zen-${Date.now()}.json`), out);
    return { ok: true, out, json: JSON.parse(out) };
  } catch (e) {
    return { ok: false, out: (e.stdout||"")+(e.stderr||""), error: String(e).slice(0,300) };
  }
}

function ledgerState() {
  const r = cli("status", "--ledger", LEDGER);
  return r.ok ? r.json.state : null;
}

function zenRequest(milestoneId) {
  const st = ledgerState();
  const m = st.milestones.find(x => x.id === milestoneId);
  const cand = st._active_candidates?.[milestoneId];
  return {
    milestone_id: milestoneId,
    plan_version: st.plan_version,
    result_ref: cand?.result_ref || "unknown",
    contract: m,
    candidate: cand?.candidate_record || cand || {},
  };
}

const scenario = process.argv[2] || "help";

switch (scenario) {

  case "reset":
    rmSync(LEDGER, { force: true });
    for (const f of ["greeting.txt","summary.txt","extra.txt"]) rmSync(join(SCRATCH,f), { force: true });
    log("reset done");
    break;

  case "init":
    cli("init", "--ledger", LEDGER, "--plan", join(EV, "plan-v1.json"));
    snap("init");
    break;

  case "m1-happy": {
    log("=== M1 happy path: run-milestone with --zen-cmd ===");
    const r = cli("run-milestone", "--ledger", LEDGER, "--milestone", "M1", "--zen-cmd", `${EV}/zen-invoke.sh`, "--timeout", "300000", "--cwd", SCRATCH);
    snap("m1-happy");
    log(`M1 result: ok=${r.ok} ${r.out.slice(0,300)}`);
    break;
  }

  case "m1-nogo": {
    log("=== M1 NO-GO: defective candidate -> Zen NO-GO ===");
    cli("delegate", "--ledger", LEDGER, "--milestone", "M1");
    // defective candidate: claims HELLO but file has WRONG_CONTENT
    writeFileSync(join(SCRATCH, "greeting.txt"), "WRONG_CONTENT\n");
    const cand = {
      milestone_id: "M1", plan_version: "v1",
      changes_made: "created greeting.txt",
      candidate_artifact_ref: "greeting.txt@WRONG_CONTENT",
      verification_evidence: [{ classification: "OBSERVED", command: "cat greeting.txt", result: "WRONG_CONTENT" }],
      scope_deviations: "wrote WRONG_CONTENT instead of HELLO", unresolved_unknowns: "none", status: "DONE",
    };
    writeFileSync(join(EV, "candidate-defective.json"), JSON.stringify(cand));
    cli("candidate", "--ledger", LEDGER, "--file", join(EV, "candidate-defective.json"));
    snap("m1-candidate");
    const req = zenRequest("M1");
    const zr = zen(req);
    writeFileSync(join(EV, "verdict-nogo.json"), zr.out);
    if (zr.ok) cli("record-zen", "--ledger", LEDGER, "--file", join(EV, "verdict-nogo.json"));
    snap("m1-nogo");
    break;
  }

  case "m1-repair": {
    log("=== M1 REPAIR: correct candidate -> fresh Zen GO ===");
    cli("delegate", "--ledger", LEDGER, "--milestone", "M1");
    writeFileSync(join(SCRATCH, "greeting.txt"), "HELLO\n");
    const cand = {
      milestone_id: "M1", plan_version: "v1",
      changes_made: "created greeting.txt with HELLO",
      candidate_artifact_ref: "greeting.txt@HELLO",
      verification_evidence: [{ classification: "OBSERVED", command: "cat greeting.txt", result: "HELLO" }],
      scope_deviations: "none", unresolved_unknowns: "none", status: "DONE",
    };
    writeFileSync(join(EV, "candidate-repair.json"), JSON.stringify(cand));
    cli("candidate", "--ledger", LEDGER, "--file", join(EV, "candidate-repair.json"));
    const req = zenRequest("M1");
    const zr = zen(req);
    writeFileSync(join(EV, "verdict-repair.json"), zr.out);
    if (zr.ok) cli("record-zen", "--ledger", LEDGER, "--file", join(EV, "verdict-repair.json"));
    snap("m1-repaired");
    break;
  }

  case "m2": {
    log("=== M2: run-milestone with --zen-cmd ===");
    const r = cli("run-milestone", "--ledger", LEDGER, "--milestone", "M2", "--zen-cmd", `${EV}/zen-invoke.sh`, "--timeout", "300000", "--cwd", SCRATCH);
    snap("m2-done");
    log(`M2 result: ok=${r.ok} ${r.out.slice(0,300)}`);
    break;
  }

  case "complete":
    log("=== declareGlobalCompletion ===");
    cli("complete", "--ledger", LEDGER);
    snap("complete");
    break;

  case "replan": {
    log("=== REPLAN ===");
    const plan2 = JSON.parse(readFileSync(join(EV, "plan-v1.json"), "utf8"));
    plan2.goal += " + extra.txt=EXTRA";
    plan2.plan_version = "v2";
    plan2.milestones.push({ id: "M3", title: "Create extra.txt", objective: "Create extra.txt containing EXTRA", acceptance_criteria: ["extra.txt exists","content is EXTRA"], depends_on: ["M2"] });
    writeFileSync(join(EV, "plan-v2.json"), JSON.stringify(plan2, null, 2));
    cli("replan", "--ledger", LEDGER, "--plan", join(EV, "plan-v2.json"));
    snap("replanned");
    break;
  }

  case "stale-verdict": {
    log("=== STALE VERDICT rejection ===");
    writeFileSync(join(EV, "stale-verdict.json"), JSON.stringify({ milestone_id: "M1", plan_version: "v1", result_ref: "stale", verdict: "GO", verification_evidence: [{ classification: "OBSERVED", criterion: "t", result: "stale" }] }));
    cli("record-zen", "--ledger", LEDGER, "--file", join(EV, "stale-verdict.json"));
    snap("stale-rejected");
    break;
  }

  case "wrong-ref": {
    log("=== WRONG RESULT_REF rejection ===");
    const st = ledgerState();
    writeFileSync(join(EV, "wrong-ref.json"), JSON.stringify({ milestone_id: "M1", plan_version: st.plan_version, result_ref: "sha256:forged", verdict: "GO", verification_evidence: [{ classification: "OBSERVED", criterion: "t", result: "forged" }] }));
    cli("record-zen", "--ledger", LEDGER, "--file", join(EV, "wrong-ref.json"));
    snap("wrong-ref-rejected");
    break;
  }

  case "resume": {
    log("=== RESUME: fresh-context from ledger ===");
    const st = ledgerState();
    log(`resumed state: plan_version=${st.plan_version} current=${st.current_milestone} completed=${JSON.stringify(st.completed_milestones)} next=${st.next_action}`);
    snap("resumed");
    break;
  }

  case "blocked": {
    log("=== BLOCKED escalation ===");
    cli("blocked", "--ledger", LEDGER, "--milestone", "M2", "--status", "BLOCKED", "--blocker", "test blocker: dependency unavailable", "--evidence", "simulated");
    snap("blocked");
    break;
  }

  case "boundary": {
    log("=== BOUNDARY: bobcat attempts non-strix subagent ===");
    const r = agy("bobcat", "Use invoke_subagent to call 'jaguar' with task 'reply PONG'. If rejected, report the exact error.", "gemini-3.6-flash-low");
    writeFileSync(join(T, "boundary-bobcat-jaguar.json"), r.out);
    log(`boundary result: ${r.out.slice(0,400)}`);
    break;
  }

  case "all":
    for (const s of ["reset","init","m1-happy","m2","complete"]) {
      execSync(`node ${join(EV,"driver.mjs")} ${s}`, { stdio: "inherit" });
    }
    break;

  default:
    console.log("scenarios: reset init m1-happy m1-nogo m1-repair m2 complete replan stale-verdict wrong-ref resume blocked boundary all");
}

#!/usr/bin/env bash
# zen-invoke.sh — external Zen invocation for spine-cli --zen-cmd.
# Reads the Zen request JSON on stdin, invokes zen via a steamroller parent
# session's invoke_subagent, extracts the verdict packet JSON, prints on stdout.
set -euo pipefail
REQ=$(cat)
SCRATCH="${SCRATCH_DIR:-/home/sleeg/work/native-gravity-evidence/44g/g3-live/scratch}"
# steamroller primary invokes zen via invoke_subagent; the request JSON is the task
PROMPT="Use invoke_subagent to call 'zen' with this exact task (pass it verbatim): $REQ

Report zen's response verbatim — the full JSON verdict packet it returns."
RESP=$(cd "$SCRATCH" && timeout 600 agy --agent steamroller --model gemini-3.1-pro-low --output-format json --print "$PROMPT" 2>/dev/null)
# save raw response for debugging
echo "$RESP" > "${SCRATCH_DIR:-/tmp}/zen-raw-$(date +%s%N).json"
# extract the verdict JSON object from the response
echo "$RESP" | node -e '
let d="";process.stdin.on("data",c=>d+=c).on("end",()=>{
  try{const j=JSON.parse(d);const r=j.response||"";
    // find the verdict JSON: look for an object containing "verdict"
    const m=r.match(/\{[^{}]*"verdict"[^{}]*"verification_evidence"[\s\S]*?\][\s\S]*?\}/);
    if(m){process.stdout.write(m[0])}
    else{const m2=r.match(/\{[\s\S]*"verdict"[\s\S]*\}/);process.stdout.write(m2?m2[0]:JSON.stringify({verdict:"NO-GO",milestone_id:"unknown",plan_version:"unknown",result_ref:"unknown",verification_evidence:[{classification:"INFERRED",criterion:"parse",result:"no verdict JSON in zen response: "+r.slice(0,300)}]}))}
  }catch(e){process.stdout.write(JSON.stringify({verdict:"NO-GO",milestone_id:"unknown",plan_version:"unknown",result_ref:"unknown",verification_evidence:[{classification:"INFERRED",criterion:"parse",result:"unparseable: "+String(e).slice(0,200)}]}))}
});'

